-- Release-1 schema.
--
-- Every foreign key is deferrable (initially immediate), so the importer can
-- run "set constraints all deferred" and load a whole bundle in one transaction.
-- The last-post pointers between forums, topics and posts form a cycle; those
-- keys are added at the end, after the three tables exist.
--
-- Rows from a bundle carry their own IDs, so the identity columns are
-- "generated by default". db.ResetSequences moves each sequence past max(id)
-- after a load.

-- ranks come first: users point at them.
create table ranks (
	id         bigint generated by default as identity primary key,
	title      text   not null default '',
	min_posts  int    not null default 0,
	special    bool   not null default false,
	image_path text   null
);

create table users (
	id               bigint generated by default as identity primary key,
	username         text   not null,
	username_clean   text   not null unique,
	email            text   not null,
	email_clean      text   not null,
	password_hash    text   not null,
	password_scheme  text   not null check (password_scheme in ('legacy', 'gobb')),
	state            text   not null check (state in ('active', 'inactive')),
	is_owner         bool   not null default false,
	email_verified   bool   not null default false,
	registered_at    timestamptz not null,
	last_visit_at    timestamptz null,
	-- The member's "mark all read" time.
	last_mark_at     timestamptz null,
	post_count       int    not null default 0,
	rank_id          bigint null
		references ranks (id) on delete set null deferrable initially immediate,
	avatar_path      text   null,
	signature_source text   not null default '',
	signature_tree   jsonb  null,
	signature_markdown bool not null default true,
	signature_smilies  bool not null default true,
	signature_autolink bool not null default true,
	timezone         text   not null default 'America/New_York',
	color_scheme     text   not null default 'slate'
		check (color_scheme in ('slate', 'slate-deep', 'slate-light')),
	notify_on_post   bool   not null default true
);

-- Two members can share an address, so this index is not unique.
create index users_email_clean_idx on users (email_clean);

-- IDs that are not imported. Their profiles answer 410.
create table gone_users (
	id bigint primary key
);

create table groups (
	id          bigint generated by default as identity primary key,
	name        text   not null,
	builtin     text   null unique
		check (builtin in ('guests', 'members', 'moderators', 'admins')),
	kind        text   not null
		check (kind in ('open', 'request', 'closed', 'hidden', 'builtin')),
	description text   not null default ''
);

create table group_members (
	group_id   bigint not null
		references groups (id) on delete cascade deferrable initially immediate,
	user_id    bigint not null
		references users (id) on delete cascade deferrable initially immediate,
	is_leader  bool   not null default false,
	is_pending bool   not null default false,
	primary key (group_id, user_id)
);

create table acl_roles (
	id          bigint generated by default as identity primary key,
	name        text   not null,
	kind        text   not null check (kind in ('forum', 'mod', 'board')),
	description text   not null default '',
	position    int    not null default 0
);

-- setting: 1 = No, 2 = Never, 3 = Yes (as in acl.Setting).
create table acl_role_settings (
	role_id bigint   not null
		references acl_roles (id) on delete cascade deferrable initially immediate,
	option  text     not null,
	setting smallint not null check (setting in (1, 2, 3)),
	primary key (role_id, option)
);

-- A grant gives a role, or one option with a setting, never both.
-- forum_id 0 means board-wide, so it has no foreign key.
create table acl_group_grants (
	id       bigint generated by default as identity primary key,
	group_id bigint   not null
		references groups (id) on delete cascade deferrable initially immediate,
	forum_id bigint   not null default 0 check (forum_id >= 0),
	role_id  bigint   null
		references acl_roles (id) deferrable initially immediate,
	option   text     null,
	setting  smallint null check (setting in (1, 2, 3)),
	check (
		(role_id is not null and option is null and setting is null)
		or (role_id is null and option is not null and setting is not null)
	)
);

create table acl_user_grants (
	id       bigint generated by default as identity primary key,
	user_id  bigint   not null
		references users (id) on delete cascade deferrable initially immediate,
	forum_id bigint   not null default 0 check (forum_id >= 0),
	role_id  bigint   null
		references acl_roles (id) deferrable initially immediate,
	option   text     null,
	setting  smallint null check (setting in (1, 2, 3)),
	check (
		(role_id is not null and option is null and setting is null)
		or (role_id is null and option is not null and setting is not null)
	)
);

create table forums (
	id            bigint generated by default as identity primary key,
	parent_id     bigint null
		references forums (id) deferrable initially immediate,
	kind          text   not null check (kind in ('category', 'forum', 'link')),
	name          text   not null default '',
	description   text   not null default '',
	rules         text   not null default '',
	link_url      text   null,
	locked        bool   not null default false,
	position      int    not null default 0,
	topic_count   int    not null default 0,
	post_count    int    not null default 0,
	last_post_id  bigint null
);

create table topics (
	id                bigint generated by default as identity primary key,
	forum_id          bigint not null
		references forums (id) deferrable initially immediate,
	title             text   not null default '',
	author_id         bigint null
		references users (id) deferrable initially immediate,
	author_name       text   not null default '',
	created_at        timestamptz not null,
	last_post_id      bigint null,
	last_post_at      timestamptz not null,
	reply_count       int    not null default 0,
	view_count        int    not null default 0,
	kind              text   not null
		check (kind in ('normal', 'sticky', 'announce', 'global')),
	locked            bool   not null default false,
	visibility        text   not null
		check (visibility in ('approved', 'unapproved', 'deleted')),
	moved_to_topic_id bigint null
		references topics (id) on delete set null deferrable initially immediate
);

create table posts (
	id              bigint generated by default as identity primary key,
	topic_id        bigint not null
		references topics (id) deferrable initially immediate,
	forum_id        bigint not null
		references forums (id) deferrable initially immediate,
	author_id       bigint null
		references users (id) deferrable initially immediate,
	author_name     text   not null default '',
	author_ip       inet   null,
	created_at      timestamptz not null,
	subject         text   not null default '',
	body_source     text   not null,
	body_tree       jsonb  not null,
	-- Plain text for search.
	body_text       text   not null,
	enable_markdown bool   not null default true,
	enable_smilies  bool   not null default true,
	enable_autolink bool   not null default true,
	enable_sig      bool   not null default false,
	visibility      text   not null
		check (visibility in ('approved', 'unapproved', 'deleted')),
	edit_count      int    not null default 0,
	edited_at       timestamptz null,
	edited_by       bigint null
		references users (id) on delete set null deferrable initially immediate,
	edit_reason     text   not null default '',
	search          tsvector generated always as (
		to_tsvector('english'::regconfig, coalesce(subject, '') || ' ' || coalesce(body_text, ''))
	) stored
);

create index posts_search_idx on posts using gin (search);
create index posts_topic_created_idx on posts (topic_id, created_at);

-- Close the cycle between forums, topics and posts.
alter table forums add constraint forums_last_post_id_fkey
	foreign key (last_post_id) references posts (id)
	on delete set null deferrable initially immediate;
alter table topics add constraint topics_last_post_id_fkey
	foreign key (last_post_id) references posts (id)
	on delete set null deferrable initially immediate;

create table polls (
	topic_id        bigint primary key
		references topics (id) on delete cascade deferrable initially immediate,
	question        text   not null default '',
	max_options     int    not null,
	ends_at         timestamptz null,
	can_change_vote bool   not null default false
);

create table poll_options (
	topic_id   bigint not null
		references polls (topic_id) on delete cascade deferrable initially immediate,
	option_id  int    not null,
	text       text   not null default '',
	vote_count int    not null default 0,
	primary key (topic_id, option_id)
);

create table poll_votes (
	topic_id  bigint not null,
	option_id int    not null,
	user_id   bigint not null
		references users (id) deferrable initially immediate,
	voter_ip  inet   null,
	primary key (topic_id, option_id, user_id),
	foreign key (topic_id, option_id) references poll_options (topic_id, option_id)
		deferrable initially immediate
);

create table attachments (
	id             bigint generated by default as identity primary key,
	post_id        bigint null
		references posts (id) deferrable initially immediate,
	position       int    not null default 0,
	-- NULL when the uploader is gone.
	uploader_id    bigint null
		references users (id) deferrable initially immediate,
	real_name      text   not null default '',
	stored_path    text   not null default '',
	mime           text   not null default '',
	size           bigint not null default 0,
	sha256         text   not null default '',
	width          int    null,
	height         int    null,
	download_count int    not null default 0,
	comment        text   not null default '',
	created_at     timestamptz not null
);

create table pms (
	id               bigint generated by default as identity primary key,
	-- NULL when the author is gone. author_name keeps the name to show.
	author_id        bigint null
		references users (id) deferrable initially immediate,
	author_name      text   not null default '',
	author_ip        inet   null,
	created_at       timestamptz not null,
	subject          text   not null default '',
	body_source      text   not null default '',
	body_tree        jsonb  not null,
	body_text        text   not null default '',
	enable_markdown  bool   not null default true,
	enable_smilies   bool   not null default true,
	enable_autolink  bool   not null default true,
	enable_sig       bool   not null default false,
	author_deleted   bool   not null default false
);

create table pm_recipients (
	pm_id      bigint not null
		references pms (id) on delete cascade deferrable initially immediate,
	user_id    bigint not null
		references users (id) deferrable initially immediate,
	kind       text   not null check (kind in ('to', 'bcc')),
	is_read    bool   not null default false,
	is_deleted bool   not null default false,
	primary key (pm_id, user_id)
);

create table topic_watches (
	user_id        bigint not null
		references users (id) deferrable initially immediate,
	topic_id       bigint not null
		references topics (id) on delete cascade deferrable initially immediate,
	notify_pending bool   not null default false,
	primary key (user_id, topic_id)
);

create table bookmarks (
	user_id  bigint not null
		references users (id) deferrable initially immediate,
	topic_id bigint not null
		references topics (id) deferrable initially immediate,
	primary key (user_id, topic_id)
);

create table topic_marks (
	user_id   bigint not null
		references users (id) deferrable initially immediate,
	topic_id  bigint not null
		references topics (id) deferrable initially immediate,
	marked_at timestamptz not null,
	primary key (user_id, topic_id)
);

create table forum_marks (
	user_id   bigint not null
		references users (id) deferrable initially immediate,
	forum_id  bigint not null
		references forums (id) deferrable initially immediate,
	marked_at timestamptz not null,
	primary key (user_id, forum_id)
);

create table mod_log (
	id         bigint generated by default as identity primary key,
	actor_id   bigint null
		references users (id) on delete set null deferrable initially immediate,
	action     text   not null default '',
	target_type text  not null default '',
	target_id  bigint not null,
	details    jsonb  not null default '{}',
	created_at timestamptz not null,
	undo_until timestamptz null,
	undone_at  timestamptz null
);

create table bans (
	id           bigint generated by default as identity primary key,
	kind         text   not null check (kind in ('user', 'email', 'ip')),
	user_id      bigint null
		references users (id) deferrable initially immediate,
	email        text   null,
	ip           cidr   null,
	reason       text   not null default '',
	reason_shown text   not null default '',
	created_at   timestamptz not null,
	ends_at      timestamptz null,
	created_by   bigint null
		references users (id) on delete set null deferrable initially immediate,
	undo_log_id  bigint null
		references mod_log (id) on delete set null deferrable initially immediate
);

create table smilies (
	id          bigint generated by default as identity primary key,
	code        text   not null unique,
	image_path  text   not null default '',
	description text   not null default '',
	position    int    not null default 0
);

create table legacy_routes (
	id           bigint generated by default as identity primary key,
	-- The old path under the base path, with no leading slash.
	path         text   not null,
	-- Query parameters that must have these values.
	match        jsonb  not null default '{}',
	-- The query parameter that holds the target ID.
	id_param     text   null,
	target_kind  text   not null check (target_kind in (
		'home', 'forum', 'topic', 'post', 'user', 'members', 'team',
		'attachment', 'avatar', 'search', 'account', 'page')),
	-- A fixed target, when id_param is null.
	target_id    bigint null,
	-- For the page kind.
	target_slug  text   null,
	-- The query parameter for the item offset that picks the page.
	offset_param text   null,
	position     int    not null default 0
);

create table legacy_files (
	-- The old path prefix under the base path.
	prefix text primary key,
	dir    text not null check (dir in ('smilies', 'ranks'))
);

-- id is the SHA-256 hex of the session token.
create table sessions (
	id           text primary key,
	user_id      bigint not null
		references users (id) on delete cascade deferrable initially immediate,
	created_at   timestamptz not null,
	last_seen_at timestamptz not null,
	expires_at   timestamptz not null,
	ip           inet   not null,
	user_agent   text   not null default '',
	remember     bool   not null default false
);

create table user_ips (
	user_id      bigint not null
		references users (id) deferrable initially immediate,
	ip           inet   not null,
	last_seen_at timestamptz not null,
	primary key (user_id, ip)
);

create table settings (
	key   text  primary key,
	value jsonb not null
);

create table email_queue (
	id              bigint generated by default as identity primary key,
	to_addr         text   not null default '',
	subject         text   not null default '',
	body            text   not null default '',
	created_at      timestamptz not null,
	attempts        int    not null default 0,
	next_attempt_at timestamptz not null,
	sent_at         timestamptz null,
	last_error      text   not null default ''
);

create table email_tokens (
	token_hash text primary key,
	user_id    bigint not null
		references users (id) on delete cascade deferrable initially immediate,
	purpose    text   not null check (purpose in ('verify', 'reset')),
	expires_at timestamptz not null,
	used_at    timestamptz null
);

create table static_pages (
	slug        text primary key,
	title       text   not null default '',
	body_source text   not null default '',
	body_tree   jsonb  not null,
	enable_markdown bool not null default true,
	enable_smilies  bool not null default true,
	enable_autolink bool not null default true,
	updated_at  timestamptz not null
);
